mod geometry {
    pub struct Point {
        pub x: f64,
        pub y: f64,
    }

    impl Point {
        pub fn distance(&self, other: &Point) -> f64 {
            ((self.x - other.x).powi(2) + (self.y - other.y).powi(2)).sqrt()
        }
    }

    pub trait Area {
        fn area(&self) -> f64;
    }

    pub enum Shape {
        Circle(f64),
        Square(f64),
    }
}

